import{_ as t,o as a,c as r,ae as o}from"./chunks/framework.EHGTsUvI.js";const g=JSON.parse('{"title":"Cake Factory","description":"","frontmatter":{},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/cakebatter.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/cakebatter.md"}'),i={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/cakebatter.md"};function n(l,e,s,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="cake-factory" tabindex="-1">Cake Factory <a class="header-anchor" href="#cake-factory" aria-label="Permalink to &quot;Cake Factory&quot;">​</a></h1><p>The <strong>Cake Factory</strong> is used to combine Wheat, Eggs, and Milk to produce <strong>Cake Batter</strong>. The Cake Batter can then be placed into an <strong>Oven Building</strong> to produce finished Cakes.</p><h2 id="factory-information" tabindex="-1">Factory Information <a class="header-anchor" href="#factory-information" aria-label="Permalink to &quot;Factory Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td><strong>Purchase price</strong></td><td>45,000 Coins</td></tr><tr><td><strong>Required materials</strong></td><td>Wheat, Eggs and Milk</td></tr><tr><td><strong>Production time</strong></td><td>Requires multiple lever stages; exact processing time is not currently documented</td></tr><tr><td><strong>Products produced</strong></td><td>Cake Batter</td></tr><tr><td><strong>Selling price</strong></td><td>Cake Batter itself is not the final product. Finished Cake sells for approximately 8,000 Coins</td></tr><tr><td><strong>Required equipment</strong></td><td>Suitable vehicle or trailer for transporting Cake Batter; Oven Building required to produce Cake</td></tr></tbody></table><p>The Cake Factory costs <strong>45,000 Coins</strong>, has storage for <strong>50 Milk, 50 Eggs and 5,000 Wheat</strong>, and has a building size of <strong>7 × 10</strong>.</p><h2 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h2><p>One Cake Batter requires:</p><table tabindex="0"><thead><tr><th>Material</th><th style="text-align:right;">Amount</th></tr></thead><tbody><tr><td>🌾 Wheat</td><td style="text-align:right;">50</td></tr><tr><td>🥚 Eggs</td><td style="text-align:right;">1 Box</td></tr><tr><td>🥛 Regular Milk</td><td style="text-align:right;">1 Jug</td></tr></tbody></table><p>Free-Range Milk can also be used. One jug of Free-Range Milk counts as two jugs of Regular Milk. Spoiled Milk cannot be used.</p><p>The factory can produce up to <strong>6 boxes of Cake Batter at a time</strong>.</p><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>The exact processing time of the Cake Factory is not currently documented as a fixed number.</p><p>Production requires the player to manually operate a sequence of levers inside the factory. Each lever requires a short waiting period before the next lever becomes available.</p><blockquote><p><strong>Note:</strong> The production time listed here should not be confused with the baking time. Once Cake Batter has been produced, it must be placed into an Oven Building.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>The Cake Factory produces <strong>Cake Batter</strong>.</p><p>Cake Batter is not the finished Cake. To turn Cake Batter into Cake, it must be placed into an <strong>Oven Building</strong>.</p><p>The Oven Building contains <strong>8 ovens</strong>, allowing up to 8 Cakes to be baked simultaneously. Current documentation lists the baking time as approximately <strong>10 minutes</strong>.</p><h2 id="selling-price" tabindex="-1">Selling Price <a class="header-anchor" href="#selling-price" aria-label="Permalink to &quot;Selling Price&quot;">​</a></h2><p>The finished <strong>Cake</strong> can be sold at AnimalCo for approximately <strong>8,000 Coins</strong> per Cake.</p><p>Cake Batter itself is an intermediate product and is therefore not the final item in the Cake production chain.</p><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>The Cake production chain requires:</p><ul><li><strong>Cake Factory</strong> — Produces Cake Batter.</li><li><strong>Oven Building</strong> — Converts Cake Batter into Cake.</li><li><strong>Suitable transport</strong> — Used to transport ingredients and collect finished Cake Batter.</li><li><strong>Chicken setup</strong> — Required to produce Eggs.</li><li><strong>Cow setup</strong> — Required to produce Milk.</li><li><strong>Wheat fields</strong> — Required to produce Wheat.</li></ul><h2 id="how-to-use-the-factory" tabindex="-1">How to Use the Factory <a class="header-anchor" href="#how-to-use-the-factory" aria-label="Permalink to &quot;How to Use the Factory&quot;">​</a></h2><h3 id="_1-load-the-ingredients" tabindex="-1">1. Load the Ingredients <a class="header-anchor" href="#_1-load-the-ingredients" aria-label="Permalink to &quot;1. Load the Ingredients&quot;">​</a></h3><p>Bring the required ingredients to the Cake Factory.</p><p>For at least one Cake Batter, you need:</p><ul><li><strong>50 Wheat</strong></li><li><strong>1 Box of Eggs</strong></li><li><strong>1 Jug of Regular Milk</strong></li></ul><p>Wheat and Milk can be deposited on the left side of the building.</p><p>Eggs are deposited inside the building onto the conveyor belt.</p><h3 id="_2-start-production" tabindex="-1">2. Start Production <a class="header-anchor" href="#_2-start-production" aria-label="Permalink to &quot;2. Start Production&quot;">​</a></h3><p>Enter the Cake Factory and locate the first lever.</p><p>When enough ingredients have been supplied, the lever will display:</p><blockquote><p><strong>Pull Lever to Begin</strong></p></blockquote><p>Pull the lever to start production.</p><p>If the message does not appear, the factory does not have enough ingredients to produce at least one batch.</p><h3 id="_3-follow-the-lever-sequence" tabindex="-1">3. Follow the Lever Sequence <a class="header-anchor" href="#_3-follow-the-lever-sequence" aria-label="Permalink to &quot;3. Follow the Lever Sequence&quot;">​</a></h3><p>After pulling the first lever, wait for the next lever to become available.</p><p>The sequence moves through several levers:</p><ol><li>First lever</li><li>Lever opposite the first</li><li>Lever below the conveyor belt</li><li>Final lever upstairs on the right</li></ol><p>Pull each lever when its prompt becomes available.</p><h3 id="_4-collect-the-cake-batter" tabindex="-1">4. Collect the Cake Batter <a class="header-anchor" href="#_4-collect-the-cake-batter" aria-label="Permalink to &quot;4. Collect the Cake Batter&quot;">​</a></h3><p>Once production is complete, the Cake Batter is delivered to the loading area on the right side of the building.</p><p>If a suitable vehicle or trailer is positioned at the loading area, the Cake Batter will automatically load onto it.</p><h3 id="_5-bake-the-cake" tabindex="-1">5. Bake the Cake <a class="header-anchor" href="#_5-bake-the-cake" aria-label="Permalink to &quot;5. Bake the Cake&quot;">​</a></h3><p>Take the Cake Batter to an <strong>Oven Building</strong>.</p><p>Place the Cake Batter onto the storage tray on the right side of the entrance.</p><p>The Oven Building will then begin baking the Cake. Current documentation states that baking takes approximately <strong>10 minutes</strong>.</p><p>Once finished, the Cakes are automatically placed onto the storage rack on the left side of the Oven Building.</p><hr><blockquote><p><strong>Note:</strong> Cake production requires several stages, from growing Wheat and producing Eggs and Milk, to making Cake Batter and finally baking it. Make sure you have both a Cake Factory and an Oven Building before starting the full production chain.</p></blockquote>',52)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
